    for k in range(n):
        x, y = data[1 + 2*k:3 + 2*k]
        p[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for j in range(1, n + 2):
        low = p[j]
        total = 0
        for i in range(j):
            high = p[i]
            if high <= low or dp[i] == 0:
                continue
            vals = []
            prefix = []
            mn = n + 2
            for k in range(i + 1, j):
                v = p[k]
                if low < v < high:
                    vals.append(v)
                    prefix.append(mn)
                    if v < mn:
                        mn = v
            mx = 0
            valid = True
            for k in range(len(vals) - 1, -1, -1):
                v = vals[k]
                if v > mx:
                    if v < prefix[k]:
                        valid = False
                        break
                    mx = v
            if valid:
                total += dp[i]
        dp[j] = total % MOD
    print(dp[-1])

if __name__ == '__main__':
    main()

