import sys

MOD = 998244353

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)

    # limit[l][k]: smallest right endpoint of a condition at k
    # whose left endpoint is at least l (half-open intervals).
    limit = [[n + 1] * n for _ in range(n + 1)]
    for _ in range(m):
        l = next(it) - 1
        r = next(it)
        x = next(it) - 1
        if r < limit[l][x]:
            limit[l][x] = r
    for l in range(n - 2, -1, -1):
        a = limit[l]
        b = limit[l + 1]
        for k in range(l, n):
            if b[k] < a[k]:
                a[k] = b[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(n + 1):
        dp[l][l] = 1
    for l in range(n - 1, -1, -1):
        row = dp[l]
        lim = limit[l]
        for r in range(l + 1, n + 1):
            total = 0
            for k in range(l, r):
                if r < lim[k]:
                    total += row[k] * dp[k + 1][r]
            row[r] = total * inv[r - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)

if __name__ == '__main__':
    main()

