import sys
from collections import deque

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    # None represents the constant row of ones.
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        row = dp[v]
        other = dp[p]
        if row is None:
            if other is None:
                dp[p] = list(range(1, m + 1))
            else:
                for j in range(m):
                    other[j] = other[j] * (j + 1) % MOD
        else:
            s = 0
            if other is None:
                for j in range(m):
                    s = (s + row[j]) % MOD
                    row[j] = s
                dp[p] = row
            else:
                for j in range(m):
                    s = (s + row[j]) % MOD
                    other[j] = other[j] * s % MOD
            dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for v in range(n):
        if deg[v] == 0:
            continue
        # All vertices of a directed cycle must have the same value.
        row = None
        u = v
        while deg[u]:
            deg[u] = 0
            cur = dp[u]
            if cur is not None:
                if row is None:
                    row = cur
                else:
                    for j in range(m):
                        row[j] = row[j] * cur[j] % MOD
            u = a[u]
        ans = ans * (m if row is None else sum(row) % MOD) % MOD
    print(ans)


if __name__ == '__main__':
    solve()

