import random, heapq, time

def fast(n, edges, x):
    adj=[[] for _ in range(2*n)]
    for u,v in edges:
        adj[u].append(v); adj[v+n].append(u+n)
    ds=[10**30]*(2*n);ds[0]=0;h=[(0,0)]
    while h:
        d,u=heapq.heappop(h)
        if d!=ds[u]:continue
        if u in (n-1,2*n-1):return d
        v=u+n if u<n else u-n
        if d+x<ds[v]:
            ds[v]=d+x;heapq.heappush(h,(d+x,v))
        for v in adj[u]:
            if d+1<ds[v]:
                ds[v]=d+1;heapq.heappush(h,(d+1,v))

def oracle(n,edges,x):
    size=2*n;d=[[10**30]*size for _ in range(size)]
    for i in range(size):d[i][i]=0
