import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * p % MOD

        # Heights are shifted so the minimum among processed vertices is zero.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue
            nd = [0] * (len(dp) + e)
            shift = [pow(p, i * d, MOD) for d in range(e + 1)]
            for h, v in enumerate(dp):
                if not v:
                    continue
                k = h + e
                nd[k] = (nd[k] + v * powers[k]) % MOD
                if h >= e:
                    k = h - e
                    nd[k] = (nd[k] + v * powers[k]) % MOD
                else:
                    # A new minimum shifts all i preceding heights upward.
                    nd[0] = (nd[0] + v * shift[e - h]) % MOD
            dp = nd
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)


if __name__ == '__main__':
    main()

