import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    m = max(a)

    # omega[x] is the number of prime factors of x, with multiplicity.
    # This is also the Grundy value of a pile containing x.
    omega = [0] * (m + 1)
    for p in range(2, m + 1):
        if omega[p] == 0:
            power = p
            while power <= m:
                for j in range(power, m + 1, power):
                    omega[j] += 1
                power *= p

    value = 0
    for x in a:
        value ^= omega[x]
    print('Anna' if value else 'Bruno')


