class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        gains = [0] * len(conflictingPairs)
        first = second = 0
        owner = 0
        total = 0

        for right in range(1, n + 1):
            # Keep the two largest active left endpoints, including ties.
            for left, idx in ending[right]:
                if left > first:
                    second = first
                    first = left
                    owner = idx
                elif left > second:
                    second = left

            total += right - first
            # Only removing the strongest constraint can help at this right.
            gains[owner] += first - second

        return total + max(gains)

