import sys

def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    q = next(it)
    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**30
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = w

    r = range(n)
    # Floyd-Warshall, maintaining symmetry explicitly.
    for k in r:
        dk = d[k]
        for i in r:
            di = d[i]
            base = di[k]
            if base == inf:
                continue
            for j in range(i + 1, n):
                v = base + dk[j]
                if v < di[j]:
                    di[j] = v
                    d[j][i] = v

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            value = d[query[1]][query[2]]
            ans.append(str(value if value < inf else -1))
            continue

        a, b, w = edges[query[1]]
        if w >= d[a][b]:
            continue
        da = d[a][:]
        db = d[b][:]
        for i in r:
            # Only an orientation improving distance to its far endpoint
            # can improve any distance starting at i.
            if da[i] + w < db[i]:
                base = da[i] + w
                dest = db
            elif db[i] + w < da[i]:
                base = db[i] + w
                dest = da
            else:
                continue
            di = d[i]
            for j in range(i + 1, n):
                v = base + dest[j]
                if v < di[j]:
                    di[j] = v
                    d[j][i] = v

    sys.stdout.write('\n'.join(reversed(ans)))

if __name__ == '__main__':
    solve()

