import sys
from math import gcd


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    hi = 10**9 + 1
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # The first machine has the better cost per unit of capacity.
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        rows.append((a, p, b, q, a // gcd(a, b)))
        hi = min(hi, budget * a // p + 1)

    def feasible(w):
        total = 0
        for a, p, b, q, limit in rows:
            best = ((w + a - 1) // a) * p
            # limit inefficient machines can be replaced at no greater cost.
            for j in range(1, min(limit, (w + b - 1) // b + 1)):
                remaining = w - j * b
                cost = j * q
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)


if __name__ == '__main__':
    solve()

