class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        # dp[k]: ways for the processed performers to use k scored stages.
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            # Descending updates preserve the previous row at dp[k - 1].
            for k in range(min(i, x), 0, -1):
                dp[k] = (dp[k] * k + dp[k - 1] * (x - k + 1) * y) % mod
            dp[0] = 0
        return sum(dp) % mod

