class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # steps[i] is the number of operations needed to reduce i to 1.
        steps = [0] * (length + 1)
        for i in range(2, length + 1):
            steps[i] = steps[i.bit_count()] + 1
        eligible = [i for i in range(1, length + 1) if steps[i] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        answer = 0
        prefix = 0
        for pos, bit in enumerate(s):
            if bit == '1':
                # First differ from s here by placing a zero.
                remaining = length - pos - 1
                subtotal = 0
                for total in eligible:
                    j = total - prefix
                    if j < 0:
                        continue
                    if j > remaining:
                        break
                    subtotal += inv[j] * inv[remaining - j] % mod
                answer = (answer + fact[remaining] * subtotal) % mod
                prefix += 1
        return answer

