def fast(u,d,x):
    v=u[:]
    for i in range(1,len(v)): v[i]=min(v[i],v[i-1]+x)
    for i in range(len(v)-2,-1,-1): v[i]=min(v[i],v[i+1]+x)
    return sum(u)+sum(d)-len(u)*min(a+b for a,b in zip(v,d))

