import sys


def optimize(offsets):
    if len(offsets) <= 1:
        return (len(offsets), len(offsets))

    even = []
    odd = []
    counts = [0, 0, 0, 0]
    for a in offsets:
        counts[a & 3] += 1
        if a & 1:
            odd.append((a + 1) // 2)
        else:
            even.append(a // 2)

    best_even = optimize(even)
    best_odd = optimize(odd)

    # Each result fixes the parity of the shift. The next shift bit
    # determines the mountain/valley types of the odd crease indices.
    return (
        max(counts[3] + best_even[0], counts[1] + best_even[1]),
        max(counts[2] + best_odd[0], counts[0] + best_odd[1]),
    )


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    offsets = data[1:]
    print(max(optimize(offsets)))


if __name__ == '__main__':
    main()

