import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for k in range(m):
        u = data[2 + 2 * k] - 1
        v = data[3 + 2 * k] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form of the adjacency matrix over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        p = next((i for i in range(rank, n)
                  if (rows[i] >> col) & 1), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    # Each free variable supplies one bit, representing a nullspace basis vector.
    pivot_set = set(pivots)
    answer = [0] * n
    bit = 1
    for col in range(n):
        if col in pivot_set:
            continue
        answer[col] = bit
        for i, p in enumerate(pivots):
            if (rows[i] >> col) & 1:
                answer[p] |= bit
        bit <<= 1

    # An identically zero coordinate in the nullspace cannot be made nonzero.
    if any(x == 0 for x in answer):
        print('No')
    else:
        print('Yes')
        print(*answer)


if __name__ == '__main__':
    main()

