            step = er*w + ec
            tail = [0] * size
            rows = range(n, 0, -1) if er == 1 else range(1, n+1)
            for r in rows:
                for k in range(r*w+1, r*w+m+1):
                    v = a[k]
                    wanted = 2 if v == 1 else 2-v
                    tail[k] = 1 + tail[k+step] if a[k+step] == wanted else 1

            step = dr*w + dc
            prefix = [0] * size
            rows = range(1, n+1) if dr == 1 else range(n, 0, -1)
