                        pv = a[p]
                        if prefix[p] and v == (2 if pv == 1 else 2-pv):
                            length = prefix[p]+1
                        else:
                            continue
                    prefix[k] = length
                    candidate = length + tail[k]-1
                    if candidate > ans:
                        ans = candidate
