from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odds, evens = (n + 1) // 2, n // 2
        unused = list(range(1, n + 1))
        answer = []
        last = -1

        while unused:
            for i, value in enumerate(unused):
                parity = value % 2
                if parity == last:
                    continue

                o = odds - parity
                e = evens - (1 - parity)
                # The suffix must begin with the opposite parity.
                if parity == 1:
                    feasible = e == o or e == o + 1
                else:
                    feasible = o == e or o == e + 1
                if not feasible:
                    continue

                # Each parity's remaining values can be ordered freely.
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    unused.pop(i)
                    odds, evens = o, e
                    last = parity
                    break
            else:
                return []

        return answer

