from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = (powers[i] + powers[j]) % k if i != j else powers[i]

        # Remaining contributions can attain exactly the multiples of
        # the gcd of k and their positional weights. Digits 0..9 cover
        # every multiple of any single weight modulo k, since k <= 9.
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        result = ['0'] * n
        remainder = 0
        for i in range(m):
            for digit in range(9, -1, -1):
                r = (remainder + digit * weights[i]) % k
                if r % suffix[i + 1] == 0:
                    result[i] = result[n - 1 - i] = str(digit)
                    remainder = r
                    break

        return ''.join(result)

