import sys

MOD = 998244353


def solve():
    inp = sys.stdin.buffer
    t = int(inp.readline())
    answers = []
    for _ in range(t):
        h, w = map(int, inp.readline().split())
        parent = [-1] * (h + w)
        parity = bytearray(h + w)
        columns = bytearray(w)
        components = h + w
        ok = True

        for i in range(h):
            s = inp.readline().strip()
            if not ok:
                continue
            row = 0
            for j, ch in enumerate(s):
                if ch == 65:
                    row ^= 1
                    columns[j] ^= 1
                else:
                    a, b = i, h + j
                    value = 1 ^ row ^ columns[j]
                    while parent[a] >= 0:
                        p = parent[a]
                        if parent[p] >= 0:
                            parity[a] ^= parity[p]
                            parent[a] = parent[p]
                        value ^= parity[a]
                        a = parent[a]
                    while parent[b] >= 0:
                        p = parent[b]
                        if parent[p] >= 0:
                            parity[b] ^= parity[p]
                            parent[b] = parent[p]
                        value ^= parity[b]
                        b = parent[b]
                    if a == b:
                        if value:
                            ok = False
                            break
                    else:
                        if parent[a] > parent[b]:
                            a, b = b, a
                        parent[a] += parent[b]
                        parent[b] = a
                        parity[b] = value
                        components -= 1
            if row:
                ok = False

        if ok and not any(columns):
            answers.append(str(pow(2, components, MOD)))
        else:
            answers.append('0')

    sys.stdout.write('\n'.join(answers))


