from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        left = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                left[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                order.append(s[x])
                end[x] = len(order)
        t = '#' + '#'.join(order) + '#'
        m = len(t)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            r = min(right - i, radius[2 * center - i]) if i < right else 0
            while i - r - 1 >= 0 and i + r + 1 < m and t[i-r-1] == t[i+r+1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center, right = i, i + r
        return [radius[left[i] + end[i]] >= end[i] - left[i] for i in range(n)]

