class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        head = 0
        for _ in range(t):
            new_head = (head - 1) % 26
            counts[head] = (counts[head] + counts[new_head]) % mod
            head = new_head
        return sum(counts) % mod

