from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        ans = 0
        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            upper = (n + i) // 2
            if z[i] >= i:
                # All second boundaries j >= 2*i satisfy the first condition.
                ans += max(0, n - 2 * i)
                upper = min(upper, 2 * i - 1)

            value = nums[i]
            # Before this row, dp[j] is LCP(nums[i+1:], nums[j:]).
            # Ascending j preserves the previous row's dp[j+1].
            for j in range(i + 1, upper + 1):
                if value == nums[j]:
                    dp[j] = dp[j + 1] + 1
                    if dp[j] >= j - i:
                        ans += 1
                else:
                    dp[j] = 0
            for j in range(upper + 1, n):
                if value == nums[j]:
                    dp[j] = dp[j + 1] + 1
                else:
                    dp[j] = 0
        return ans

