from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Process symmetric pairs from the outside toward the center.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = []
        for a, b in states:
            transitions.append([
                k for k, (x, y) in enumerate(states)
                if x != a and y != b
            ])

        # dp[k]: minimum cost with the most recent pair in state k.
        dp = [0] * 6
        for i in range(n // 2):
            left, right = cost[i], cost[n - 1 - i]
            nxt = []
            for k, (a, b) in enumerate(states):
                x, y, z = transitions[k]
                nxt.append(left[a] + right[b] + min(dp[x], dp[y], dp[z]))
            dp = nxt
        return min(dp)

