class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        previous = current = gain = 0
        # Removing an internal one-run merges its two neighboring zero-runs.
        # Flipping that merged run gains exactly the lengths of those zero-runs.
        for ch in s + '1':
            if ch == '0':
                current += 1
            elif current:
                if previous:
                    gain = max(gain, previous + current)
                previous = current
                current = 0
