def runs(t, ch):
    i = 0
    while i < len(t):
        j = i+1
        while j < len(t) and t[j] == t[i]: j += 1
        if t[i] == ch and i > 0 and j < len(t): yield i,j
        i = j

def brute(s):
    t = '1'+s+'1'
    ans = s.count('1')
    for i,j in runs(t,'1'):
        u = t[:i]+'0'*(j-i)+t[j:]
        for a,b in runs(u,'0'):
            v = u[:a]+'1'*(b-a)+u[b:]
            ans = max(ans,v.count('1')-2)
    return ans
