from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        available = set(map(tuple, points))
        best = -1
        for i, (x1, y1) in enumerate(points):
            for x2, y2 in points[i + 1:]:
                if x1 == x2 or y1 == y2:
                    continue
                if (x1, y2) not in available or (x2, y1) not in available:
                    continue
                left, right = sorted((x1, x2))
                bottom, top = sorted((y1, y2))
                count = sum(left <= x <= right and bottom <= y <= top for x, y in points)
                if count == 4:
                    best = max(best, (right - left) * (top - bottom))
        return best

